import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Chunk Certificates","description":"","frontmatter":{"title":"Chunk Certificates","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"proposed","status_note":"Accepted — a certificate is a signed statement, verified before load."},"headers":[],"relativePath":"handl/project/adrs/0067-chunk-certificates.md","filePath":"vendored/handl/project/adrs/0067-chunk-certificates.md"}`),a={name:`handl/project/adrs/0067-chunk-certificates.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0067-chunk-certificates" tabindex="-1">ADR-0067: Chunk Certificates <a class="header-anchor" href="#adr-0067-chunk-certificates" aria-label="Permalink to “ADR-0067: Chunk Certificates”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>A certificate is an Ed25519 detached signature</strong> over the canonical serialization of: chunk content hash (BLAKE3), dependency hashes, capability set, <code>replaces</code> targets, <code>scheme_version</code>, author id, timestamp and certificate version.</li><li><strong>Verification happens before load</strong>: recompute the hash, verify the signature, check the author in the trust store, check the capability policy (ADR-0046), then verify every dependency&#39;s certificate. A failure means the chunk is never loaded, decompressed or typechecked.</li><li><strong>Dependency certificates are required</strong> and pin each dependency&#39;s content hash; a same-id/different-content dependency fails, closing supply-chain substitution.</li><li><strong>Author keys are distributed out of band</strong> — key server, pinned host config, or Web-of-Trust; the certificate carries the author id, not the key.</li><li><strong>Certificates complement capability checks</strong>: ADR-0046 inspects what the data may do; this verifies the data is intact and from a trusted author.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Content hashes proved identity but not provenance: anyone could publish a chunk with a matching id and different content, and capability checks cannot tell tampering from intent. A signed statement over hash + deps + capabilities makes substitution detectable before any code runs.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Verify after load</strong> — too late; the chunk must be rejected first.</li><li><strong>Trust on first use</strong> — authors are in a trust store, not learned.</li><li><strong>Skip dependency verification</strong> — a chain is only as strong as its edges.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Loading is gated on signature + trust + capabilities.</li><li>Authors must publish keys; hosts must maintain a trust store.</li><li>Dependency hashes become part of the certificate, so substitution fails.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>handl-pkg-vendor/</code> — certificate creation and verification.</li><li><code>handl-runtime/</code> — pre-load verification path.</li><li>Tests for tampered chunks, untrusted authors and substituted deps.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The certificate shape, verification order and dependency rules: +<a href="./../design/0067-chunk-certificates.html"><code>design/0067-chunk-certificates.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};